def input_mapping(x, B): 
    if B is None:
        return x
    else:
        x_proj = (2.*np.pi*x) @ B.T
        return np.concatenate([np.sin(x_proj), np.cos(x_proj)], axis=-1)

class Embeddings(nn.Module):
    "The embedding module from word, position and token_type embeddings."
    def __init__(self, cfg):
        super().__init__()
        self.operation_with_pos_encoding = cfg["operation_with_pos_encoding"]

        self.pos_embed = nn.Embedding(cfg["max_len"], cfg["dim"]) 
        if cfg["operation_with_pos_encoding"] == "concatenate":
            self.pos_embed_3DLin_GaussMap = nn.Linear(512, int(cfg["dim"]/2)) # position embedding: x,y,t or 512 after gaussian-fourier mapping
            if self.Spectral_normalization:
                self.pos_embed_3DLin = SpectralNorm(nn.Linear(3, int(cfg["dim"]/2))) # position embedding: x,y,t or 512 after gaussian-fourier mapping
            else:
                self.pos_embed_3DLin = nn.Linear(3, int(cfg["dim"]/2)) # position embedding: x,y,t or 512 after gaussian-fourier mapping

        elif cfg["operation_with_pos_encoding"] == "sum":   
            self.pos_embed_3DLin = nn.Linear(3, cfg["dim"]) # position embedding: x,y,t or 512 after gaussian-fourier mapping
        self.max_len = cfg["max_len"]
        self.frame_size = cfg["frame_size"]
        self.patch_size = cfg["patch_size"]
        self.norm = LayerNorm(cfg)
        self.drop = nn.Dropout(cfg["p_drop_hidden"])

    def forward(self, x, T, P_row, P_col, map_fn):
        verbose =False

        pos_t = (T/(self.max_len-1)) 
        pos_t = pos_t.unsqueeze(0).T 

        pos_x = (P_row/(self.frame_size["rows"] - self.patch_size[0]-1))
        pos_x = pos_x.unsqueeze(0).T # (S,) -> (B, S) 

        pos_y = (P_col/(self.frame_size["cols"] - self.patch_size[1]-1))
        pos_y = pos_y.unsqueeze(0).T # (S,) -> (B, S) 

        mapped_input = input_mapping(torch.cat((pos_t, pos_x, pos_y), 1), map_fn)

        if map_fn is None: 
            pos_embed_result = self.pos_embed_3DLin(torch.Tensor(mapped_input).type_as(x)).unsqueeze(0)

        else: 
            pos_embed_result = self.pos_embed_3DLin_GaussMap(torch.Tensor(mapped_input).type_as(x)).unsqueeze(0)

        pos_embed_result = pos_embed_result.expand_as(x) # (S,) -> (B, S)

        if self.operation_with_pos_encoding == "concatenate":
            e = torch.cat((x,pos_embed_result),dim=-1)
        elif self.operation_with_pos_encoding == "sum":   
            e = x + pos_embed_result 
        return self.drop(self.norm(e))

def gaussian_orthogonal_random_matrix(nb_rows, nb_columns, scaling = 0, device = None):
    nb_full_blocks = int(nb_rows / nb_columns)

    block_list = []

    for _ in range(nb_full_blocks):
        q = orthogonal_matrix_chunk(nb_columns, device = device)
        block_list.append(q)

    remaining_rows = nb_rows - nb_full_blocks * nb_columns
    if remaining_rows > 0:
        q = orthogonal_matrix_chunk(nb_columns, device = device)
        block_list.append(q[:remaining_rows])

    final_matrix = torch.cat(block_list)

    if scaling == 0:
        multiplier = torch.randn((nb_rows, nb_columns), device = device).norm(dim = 1)
    elif scaling == 1:
        multiplier = math.sqrt((float(nb_columns))) * torch.ones((nb_rows,), device = device)
    else:
        raise ValueError(f'Invalid scaling {scaling}')

    return torch.diag(multiplier) @ final_matrix

def linear_attention(q, k, v):
    verbose = False
    k_cumsum = k.sum(dim = -2)
    D_inv = 1. / torch.einsum('...nd,...d->...n', q, k_cumsum.type_as(q))
    context = torch.einsum('...nd,...ne->...de', k, v)
    out = torch.einsum('...de,...nd,...n->...ne', context, q, D_inv)
    return out

def generalized_kernel(data, *, projection_matrix, kernel_fn = nn.ReLU(), kernel_epsilon = 0.001, normalize_data = True, device = None):
    b, h, *_ = data.shape

    data_normalizer = (data.shape[-1] ** -0.25) if normalize_data else 1.

    if projection_matrix is None:
        return kernel_fn(data_normalizer * data) + kernel_epsilon

    projection = repeat(projection_matrix, 'j d -> b h j d', b = b, h = h)
    projection = projection.type_as(data)

    data_dash = torch.einsum('...id,...jd->...ij', (data_normalizer * data), projection)

    data_prime = kernel_fn(data_dash) + kernel_epsilon
    return data_prime.type_as(data)

class FastAttention(nn.Module):
    """ Linear attention from the Performer
    Original implementation: https://github.com/lucidrains/performer-pytorch/
    """
    def __init__(self, dim_heads, nb_features = None, ortho_scaling = 0, causal = False, generalized_attention = False, kernel_fn = nn.ReLU(), no_projection = False):
        super().__init__()
        verbose = False
        nb_features = default(nb_features, int(dim_heads * math.log(dim_heads)))

        self.dim_heads = dim_heads
        self.nb_features = nb_features
        self.ortho_scaling = ortho_scaling

        self.create_projection = partial(gaussian_orthogonal_random_matrix, nb_rows = self.nb_features, nb_columns = dim_heads, scaling = ortho_scaling)
        projection_matrix = self.create_projection()
        self.register_buffer('projection_matrix', projection_matrix)

        self.generalized_attention = generalized_attention
        self.kernel_fn = kernel_fn

        # if this is turned on, no projection will be used
        # queries and keys will be softmax-ed as in the original efficient attention paper
        self.no_projection = no_projection

        self.causal = causal
        if causal:
            try:
                import fast_transformers.causal_product.causal_product_cuda
                self.causal_linear_fn = partial(causal_linear_attention)
            except ImportError:
                print('unable to import cuda code for auto-regressive Performer. will default to the memory inefficient non-cuda version')
                self.causal_linear_fn = causal_linear_attention_noncuda

    @torch.no_grad()
    def redraw_projection_matrix(self, device):
        projections = self.create_projection(device = device)
        self.projection_matrix.copy_(projections)
        del projections

    def forward(self, q, k, v):
        device = q.device

        if self.no_projection:
            q = q.softmax(dim = -1)
            k = torch.exp(k) if self.causal else k.softmax(dim = -2)

        elif self.generalized_attention:
            create_kernel = partial(generalized_kernel, kernel_fn = self.kernel_fn, projection_matrix = self.projection_matrix, device = device)
            q, k = map(create_kernel, (q, k))

        else:
            create_kernel = partial(softmax_kernel, projection_matrix = self.projection_matrix, device = device)
            q = create_kernel(q, is_query = True)
            k = create_kernel(k, is_query = False)

        attn_fn = linear_attention if not self.causal else self.causal_linear_fn
        out = attn_fn(q, k, v)
        return out

class MultiHeadedSelfAttention(nn.Module):
    """ Multi-Headed Dot Product Attention """
    def __init__(self, cfg):
        super().__init__()

        self.proj_q = nn.Linear(cfg["dim"], cfg["dim"])
        self.proj_k = nn.Linear(cfg["dim"], cfg["dim"])
        self.proj_v = nn.Linear(cfg["dim"], cfg["dim"])

        self.drop = nn.Dropout(cfg["p_drop_attn"])
        self.scores = None # for visualization
        self.n_heads = cfg["n_heads"]
        self.fast_attention = cfg["fast_attention"]
        if self.fast_attention:
            self.attn_fn = FastAttention(
                dim_heads = cfg["dim"]//cfg["n_heads"],
                generalized_attention = True,
                causal = False
            )

    def forward(self, x, mask):
        B,S,D = x.shape
        q, k, v = self.proj_q(x), self.proj_k(x), self.proj_v(x)
        q, k, v = (split_last(x, (self.n_heads, -1)).transpose(1, 2)
                   for x in [q, k, v])

        if self.fast_attention:
            h = self.attn_fn(q, k, v) # (1, 8, 512, 64) 
            h = h.transpose(1,2)
            scores = None # fix it later to get the attention. 

        else: 
            scores = q @ k.transpose(-2, -1) / np.sqrt(k.size(-1))
            if mask is not None:
                mask = torch.FloatTensor(mask[:, None, None, :]).type_as(x)
                scores -= 10000.0 * (1.0 - mask)
            scores = self.drop(F.softmax(scores, dim=-1))
            h = (scores @ v).transpose(1, 2).contiguous()

        h = merge_last(h, 2)

        self.scores = scores
        return h, scores

def sampling_full_frames(data, T, patch_sampling_cfg, frame_size, patch_size, T_fixed):
    verbose=False
    num_in_between_frames = patch_sampling_cfg["num_in_between_frames"]
    if num_in_between_frames>0:
        sampling_type = patch_sampling_cfg["sampling_type"]

    if T is None: 
        T = torch.arange(0,data.shape[1]-1) # Select T samples with 

    if verbose: print('[sampling_full_frames] T: ',T)

    #Add in-between frames
    if num_in_between_frames > 0:
        if sampling_type == 'random':
            if T_fixed is None:
                in_between_frames,_ = torch.sort(torch.FloatTensor(num_in_between_frames).uniform_(T[0], T[-1]))
                T_tmp,_ = torch.sort(torch.cat((T,in_between_frames))) # append the in-between and sort
            else: # In this case, T_fixed already has some coordinates that we will include, so just sample the difference
                in_between_frames,_ = torch.sort(torch.FloatTensor(num_in_between_frames-T_fixed.size(0)).uniform_(T[0], T[-1]))
                T_tmp,_ = torch.sort(torch.cat((T,T_fixed,in_between_frames))) # append the in-between and sort


        else: 
            # just get the original coordinates of the data
            T_tmp = torch.linspace(T[0], T[-1], steps=160) # just get the original coordinates of the data
            ids_downsampled = np.linspace(0,len(T_tmp)-1,num=num_in_between_frames+len(T), dtype=np.int64)
            T_tmp = T_tmp[ids_downsampled]
            idx_overlapping = [np.argmin(np.abs(T_tmp.numpy()-T[idx].numpy())) for idx in range(len(T))] #Select the indexes that match the first 5 points used before
            idx_non_overlapping = np.argwhere(np.isin(np.arange(len(T_tmp)),idx_overlapping,invert=True)).flatten()
            in_between_frames = T_tmp[idx_non_overlapping]
            T_tmp,_ = torch.sort(torch.cat((T,in_between_frames))) # append the in-between and sort


        #Check if there are duplicates and resample if there are
        dup=np.array([0])
        while dup.size != 0:
            u, c = np.unique(T_tmp, return_counts=True)
            dup = u[c > 1]
            if dup.size != 0:
                print('[sampling_full_frames] There are duplicated time coordinates: ',dup)
                print('Resampling')

                #Add in-between frames
                if T_fixed is None:
                    in_between_frames,_ = torch.sort(torch.FloatTensor(num_in_between_frames).uniform_(T[0], T[-1]))
                    T_tmp,_ = torch.sort(torch.cat((T,in_between_frames))) # append the in-between and sort
                else:
                    in_between_frames,_ = torch.sort(torch.FloatTensor(num_in_between_frames-T_fixed.size(0)).uniform_(T[0], T[-1]))
                    T_tmp,_ = torch.sort(torch.cat((T,T_fixed,in_between_frames))) # append the in-between and sort


        T = T_tmp
        del T_tmp

    P_row = torch.zeros_like(T,dtype=torch.int64)
    P_col = torch.zeros_like(T,dtype=torch.int64)

    return T, P_row, P_col

def sampling_segments(data, T, T_orig, P_row, P_col, patch_sampling_cfg, frame_size, patch_size):
    verbose=False

    num_patches = patch_sampling_cfg["num_patches"]
    num_frames = patch_sampling_cfg["num_frames"] 
    n_pred = patch_sampling_cfg["num_patches_to_hide"] 
    n_frames_to_hide = patch_sampling_cfg["n_frames_to_hide"] 
    in_between_frame_init = patch_sampling_cfg["in_between_frame_init"]
    num_in_between_frames = patch_sampling_cfg["num_in_between_frames"]
    prob_replace_masked_token = patch_sampling_cfg["prob_replace_masked_token"]
    masking_type = patch_sampling_cfg["masking_type"]
    mode = patch_sampling_cfg["mode"]
    batch_size_segments = data.shape[0]
    if in_between_frame_init == 'interpolation':
        interpolation_kind = patch_sampling_cfg["interpolation_kind"]

    segm_frames = torch.zeros((batch_size_segments,T.shape[0],patch_size[0]*patch_size[1]),dtype=torch.float32)

    dict_special_tokens = {
        "MASK": 0.5
    }
    MASK_FRAME = torch.tensor(np.ones(patch_size[0]*patch_size[1])*dict_special_tokens["MASK"], requires_grad=True)
    if in_between_frame_init == 'interpolation':
        if verbose: print('Using interpolation for the initialization')
        data_flat = torch.flatten(data, start_dim=2)
        tmp_time = np.sort(np.random.choice(np.arange(T_orig.shape[0]), n_frames_to_hide, replace=False)) 

        t_lin= T_orig[tmp_time]
        if verbose: print('t_lin: ',t_lin)
        x_lin = data_flat[:,tmp_time]
        if verbose: print('x_lin: ',x_lin)
        f = interpolate.interp1d(t_lin, x_lin.cpu().detach().numpy(),axis=1,kind=str(interpolation_kind))

        segm_frames = torch.Tensor(f(T)).to(device)
        if verbose: print('segm_frames.shape: ',segm_frames.shape)  
        del t_lin, x_lin, tmp_time


    elif in_between_frame_init != 'interpolation':
        segm_frames = MASK_FRAME*torch.ones((batch_size_segments,T.shape[0],patch_size[0]*patch_size[1]),dtype=torch.float32)
        for idx1 in range(batch_size_segments):
            for idx in range(len(T)):
                if T[idx] in T_orig:
                    if verbose: print('using the real coordinates: {}, T[idx]: {}'.format(idx,T[idx]))
                    tmp_idx = (T_orig == T[idx]).nonzero(as_tuple=True)[0]
                    segm_frames[idx1,idx, :] = data[idx1,tmp_idx, P_row[tmp_idx]:P_row[tmp_idx]+patch_size[0], P_col[tmp_idx]:P_col[tmp_idx]+patch_size[1]].flatten()
                else:
                    if in_between_frame_init == 'mask':
                        if verbose: print('Masking idx with cte: {}, T[idx]: {}'.format(idx,T[idx]))
                        segm_frames[idx1, idx, :] = MASK_FRAME
                    elif in_between_frame_init == 'random':
                        if verbose: print('Masking idx with random: {}, T[idx]: {}'.format(idx,T[idx]))
                        segm_frames[idx1, idx, :] = torch.FloatTensor(patch_size[0], patch_size[1]).uniform_(-1.0, 1.0).squeeze()

    if in_between_frame_init == 'interpolation':
        n_pred = data.shape[1]
        cand_pos = np.argwhere(np.isin(T.numpy(),T_orig)).flatten() 
        tmp_masked_tokens = torch.empty(batch_size_segments, n_pred, segm_frames.shape[2]) 


    else: 

        if n_pred==1 and n_frames_to_hide==1:
            cand_pos = np.arange(segm_frames.shape[1]-n_pred, segm_frames.shape[1])
            tmp_masked_tokens = torch.empty(batch_size_segments, n_pred, segm_frames.shape[2]) 
        elif n_pred==1 and n_frames_to_hide>1:
            if masking_type=='last_n_points':
                cand_pos = np.arange(segm_frames.shape[1]-n_frames_to_hide, segm_frames.shape[1])
            elif masking_type=='equal_spaced':
                n_frames_to_keep = segm_frames.shape[1]-n_frames_to_hide
                cand_pos = np.argwhere(np.isin(np.arange(len(T)),np.floor(np.linspace(0,len(T),n_frames_to_keep)),invert=False)).flatten()
            elif masking_type=='random_masking':
                if mode=='inference': 
                    idx_real_coordinates = np.argwhere(np.isin(T,T_orig,invert=False)).flatten()
                    random.shuffle(idx_real_coordinates)
                    cand_pos = idx_real_coordinates[:3]

                else: 
                    if num_in_between_frames>0:
                        idx_real_coordinates = np.argwhere(np.isin(T,T_orig,invert=False)).flatten()
                        random.shuffle(idx_real_coordinates)
                        cand_pos = idx_real_coordinates[:n_frames_to_hide]

                    else:
                        cand_pos = np.arange(0,len(T))
                        random.shuffle(cand_pos)
                        if verbose: print('cand_pos: ',cand_pos)


            tmp_masked_tokens = torch.empty(batch_size_segments, n_frames_to_hide, segm_frames.shape[2]) 
            n_pred=n_frames_to_hide
            cand_pos = np.sort(cand_pos[:n_pred])

    tmp_masked_pos = []

    if in_between_frame_init == 'interpolation':
        for idx1 in range(batch_size_segments):
            for pos, idx_pos in zip(cand_pos[:n_pred], range(n_pred)):
                tmp_masked_tokens[idx1, idx_pos, :] = data[idx1, idx_pos, :].flatten()
                tmp_masked_pos.append(pos)
    else: 
        if verbose: print('Using masking. The is in_between_frame_init = ', in_between_frame_init)

        for idx1 in range(batch_size_segments):
            for pos, idx_pos in zip(cand_pos[:n_pred], range(n_pred)):
                if verbose: print('tmp_masked_tokens[{}, {}, :] = segm_frames[{}, {}, :]'.format(idx1, idx_pos,idx1,pos))
                tmp_masked_tokens[idx1, idx_pos, :] = segm_frames[idx1, pos, :]    
                tmp_masked_pos.append(pos)
                prob = random.random()
                if prob < prob_replace_masked_token:
                    segm_frames[idx1, pos, :] = MASK_FRAME
                elif prob < 0.9:
                    rand_curve = np.random.randint(batch_size_segments)
                    if verbose: print('rand_curve: ',rand_curve)
                    rand_token = np.random.randint(data.shape[1])
                    if verbose: print('rand_token: ',rand_token)
                    segm_frames[idx1, pos, :] = data[rand_curve, rand_token, :].squeeze(-1)


    masked_pos = torch.tensor(np.array(tmp_masked_pos, dtype=np.int64)).reshape(batch_size_segments,n_pred)
    masked_pos = torch.from_numpy(np.array(masked_pos))

    masked_tokens = tmp_masked_tokens.reshape(batch_size_segments,n_pred, patch_size[0], patch_size[1])
    if verbose: print('[sampling_segments] masked_tokens.shape: ', masked_tokens.shape)
    masked_tokens = masked_tokens.type_as(data)

    return T, P_row, P_col, segm_frames, masked_pos, masked_tokens

class BERT_Model(pl.LightningModule):
    def __init__(self,
                 cfg, 
                 patch_sampling_cfg,
                 train_cfg,my_loss=None,
                 path_to_save_models=None,
                 warmup=100,
                 n_labels=1, **kwargs):
        super().__init__()

        sampling_type = patch_sampling_cfg["structure"]
        self.in_between_frame_init = patch_sampling_cfg["in_between_frame_init"]

        self.sobolev_loss_ = my_loss

        self.save_best_model = SaveBestModel_CST()
        self.path_to_save_models = path_to_save_models
        self.val_loss = []
        self.warmup=warmup
        self.epoch_counter=0

        if sampling_type not in ["grid", "random"]:
            print(f"sampling type '{sampling_type}' not recognized, using random instead")
            patch_sampling_cfg["structure"] = "random"

        model_type = cfg["model_type"]
        print('model_type: ',model_type)
        if model_type not in ["linear_encoder", "conv_encoder"]:
            print(f"model type '{sampling_type}' not recognized, using 'linea_encoder' instead")
            cfg["model_type"] = model_type = "linear_encoder"

        if model_type == "linear_encoder":
            self.model = BERT_LinearEncoder(cfg, n_labels)

        elif model_type == "conv_encoder":
            self.model = BERT_ConvEncoder(cfg, n_labels)

        if cfg["plot_predictions"] == False:
            cfg["plotting"] = False

        self.save_hyperparameters()

    def forward(self, latentVar, T, P_row, P_col, map_fn, input_mask, masked_pos):
        verbose=False

        h, scores, embedded_patches = self.model.transformer(latentVar, T, P_row, P_col, map_fn, input_mask.float())
        embedded_patches_lastLayer = h.clone().detach()

        masked_pos = masked_pos[:, :, None].expand(-1, -1, h.size(-1))
        masked_pos = masked_pos.type_as(latentVar)
        masked_pos = torch.as_tensor(masked_pos, dtype=torch.int64)
        h_masked = torch.gather(h, 1, masked_pos) # Selects the tokens specified by 'masked_pos' from 'h'
        if verbose: 
            print('[in forward] masked_pos.shape: ',masked_pos.shape)
            print('[in forward] h_masked [normal].shape: ',h_masked.shape)
        h_masked = self.model.norm(self.model.activ2(self.model.linear(h_masked)))

        logits_lm = self.model.decoder(h_masked)


        logits_lm = logits_lm.reshape(logits_lm.shape[0], logits_lm.shape[1], self.hparams.cfg["patch_size"][0], self.hparams.cfg["patch_size"][1])
        return logits_lm,scores, embedded_patches, embedded_patches_lastLayer

    def training_step(self, batch, batch_idx):
        verbose=False
